mapper.insert:
BEGIN
INSERT INTO TB_PRODUCT_RATE( rate_group, rate_label, annual_rate, annual_return_rate, note, display_order, use_yn) VALUES( #{rate_group}, #{rate_label}, #{annual_rate, jdbcType=VARCHAR}, #{annual_return_rate, jdbcType=VARCHAR}, #{note, jdbcType=VARCHAR}, #{display_order}, #{use_yn}) RETURNING rate_no INTO #{rate_no, mode=OUT, jdbcType=NUMERIC};
END;
